from gen import D
ERW="Extended-release products hold far more drug than a single immediate-release tablet, released slowly over many hours. If the release system is damaged, chewed, crushed, dissolved, or taken with alcohol (for some products), the whole reserve can be released at once, which has caused many overdose deaths. ER products are meant only for people with established opioid tolerance and ongoing pain, and they should never be split or shared. Because they last so long, overdose can develop slowly, often during sleep."
ER={
"oxycodone":("Immediate-release oxycodone (Roxicodone, Oxaydo, RoxyBond, generic tablets and capsules, Percocet and other combinations) starts within about 10 to 30 minutes and lasts about 4 to 6 hours, with a noticeable rise, peak, and fall. Extended-release oxycodone (OxyContin, Xtampza ER) is designed to release drug over about 12 hours: it starts more slowly, rises gently, and gives a flatter, steadier effect with little sense of a 'high' when taken as prescribed. Patients describe OxyContin as background pain control rather than a distinct experience, with drowsiness and constipation more noticeable than mood changes.","OxyContin was reformulated in 2010 with abuse-deterrent properties. Xtampza ER uses a microsphere-in-capsule design."),
"morphine":("Immediate-release morphine (tablets, oral solution, Sevredol, Oramorph) works within about 15 to 30 minutes and lasts about 4 hours, with a clearly felt rise and dreamy peak. Extended-release morphine (MS Contin, Kadian, the discontinued Avinza and Arymo ER) releases over 12 or 24 hours with a slow onset, low peak, and steady sedation; patients mainly notice steady pain relief, constipation, and sleepiness.","Kadian and Avinza capsules contain pellets; Avinza was discontinued and had a warning about alcohol releasing all drug at once."),
"hydrocodone":("Immediate-release hydrocodone in the US comes only in combination products (Norco, Vicodin, Lortab with acetaminophen; Vicoprofen with ibuprofen), with an onset of about 10 to 60 minutes and duration of 4 to 8 hours. Extended-release single-ingredient hydrocodone (Zohydro ER capsules, given every 12 hours; Hysingla ER tablets, given every 24 hours) has a slow, flat, long profile without acetaminophen.","Zohydro ER drew controversy when approved in 2013 without abuse-deterrent features; it was later reformulated. Hysingla ER is abuse-deterrent."),
"oxymorphone":("Immediate-release oxymorphone (Opana and generics) lasts about 4 to 6 hours. Extended-release oxymorphone (Opana ER) was given every 12 hours and had a slower, longer, steadier profile. Reformulated Opana ER was removed from the US market in 2017, though some generic ER oxymorphone remained for a time.","The withdrawn reformulation is linked to the 2015 HIV and hepatitis C outbreak in Indiana."),
"hydromorphone":("Immediate-release hydromorphone (Dilaudid tablets and liquid) works quickly, often within 15 to 30 minutes, and lasts about 4 hours, with a fast, strong peak. Extended-release hydromorphone (Exalgo, once daily, discontinued in the US; Jurnista and Hydromorph Contin elsewhere) gives a very slow, flat, all-day effect for opioid-tolerant patients.","Palladone, an earlier once-daily capsule, was withdrawn in 2005 because alcohol could release all of its drug at once."),
"tramadol":("Immediate-release tramadol (Ultram, generics, Ultracet with acetaminophen) starts within about 15 to 60 minutes and lasts about 6 hours. Extended-release tramadol (Ultram ER, ConZip, the discontinued Ryzolt) is taken once daily, with a slower rise and steadier, milder effect.","ER tramadol still carries seizure and serotonin syndrome risk."),
"tapentadol":("Immediate-release tapentadol (Nucynta) starts within about 15 to 30 minutes and lasts about 4 to 6 hours. Extended-release tapentadol (Nucynta ER), taken every 12 hours, is approved for chronic pain and diabetic nerve pain, with a slow, flat profile.","Nucynta ER should not be taken with alcohol."),
"alprazolam":("Immediate-release alprazolam (Xanax, generics, Niravam orally disintegrating tablets) starts within about 15 to 30 minutes, with a noticeable calming wave and an effect that lasts about 6 to 8 hours, followed in some people by rebound anxiety. Extended-release alprazolam (Xanax XR) is taken once daily for panic disorder; it rises slowly, feels steadier and less 'hit-like', and has less rebound between doses.","Breaking or crushing XR tablets defeats the slow release and can cause sudden heavy sedation."),
"morphine-er":None,
"methadone":("Methadone has no separate extended-release product; its own long half-life acts like a built-in extended release, which is why it is taken once daily.",""),
"buprenorphine":("Buprenorphine's long-acting forms include the Butrans patch (7 days), Sublocade (monthly injection), and Brixadi (weekly or monthly injection), all designed to release steadily without peaks.",""),
"fentanyl":("Fentanyl's long-acting form is the transdermal patch (Duragesic and generics), which releases drug over 72 hours; the fast-acting forms (Actiq, Fentora, Abstral, Subsys, Lazanda) are for breakthrough cancer pain only.","Patches hold a large reserve; heat and damage are deadly."),
"zolpidem":None,
"clonazepam":("Clonazepam has no extended-release form; it is naturally long-acting.",""),
"lorazepam":("Lorazepam is mostly immediate-release; Loreev XR is a once-daily extended-release capsule approved in 2021 for people already stable on lorazepam, giving steadier levels.",""),
"codeine":("Codeine is mostly immediate-release. Extended-release codeine (Codeine Contin) is sold in Canada, and Tuzistra XR is an extended-release cough suspension in the US.",""),
}
def er(slug):
    v=ER.get(slug)
    if not v: return ""
    t,extra=v
    s=f"## Immediate-release vs extended-release\n\n{t}"
    if extra: s+=f" {extra}"
    if slug in("oxycodone","morphine","hydrocodone","oxymorphone","hydromorphone","tramadol","tapentadol","fentanyl"): s+=f"\n\n**Extra risks of extended-release:** {ERW}"
    if slug=="alprazolam": s+="\n\n**Extra risks of extended-release:** XR tablets contain more drug released over the day; if the release is defeated or the tablets are taken with alcohol or opioids, sedation and blackout can be sudden and heavy."
    return s+"\n\n"
